"use strict";

const crypto = require("crypto");

module.exports = function packageIntegrityProbe() {
  const manifest = {
    name: "package-integrity-probe",
    files: ["index.js", "package.json"],
    phase: 9,
  };
  const digest = crypto.createHash("sha256")
    .update(JSON.stringify(manifest))
    .digest("hex")
    .slice(0, 12);
  return {
    digest,
    summary: `integrity:sha256/${digest.length}/${/^[0-9a-f]+$/.test(digest)}`,
  };
};
